def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transformed'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs:
        nb['transformed'] = True
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['placed_count'] = int(nb.get('placed_count', 0)) + 1
    pc = getv(ctx, 'world.placed_count', None)
    if isinstance(pc, int) and pc > int(nb.get('placed_count', 0)):
        nb['placed_count'] = pc
    holding = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and 'not carrying' not in inv and 'nothing' not in inv and target and target not in inv)
    if wrong:
        stage = 'wrong_inventory'
    elif holding and verb and not nb.get('transformed'):
        stage = 'transform'
    elif holding and target and act.startswith('put ') and target in act and 'you put' in obs and (not dest or dest in act):
        stage = 'put_target'
    elif holding:
        stage = 'go_destination'
    else:
        stage = 'take_target' if (target and getv(ctx, 'world.target_found', False)) else 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_transform'] = verb
    return None

