def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    verb = nb.get('required_transform') or ''
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'Inventory appears to hold a non-target item. Do not place it as the goal object; recover by setting it aside only if needed, then find the requested target type.'
    elif stage == 'transform' and verb:
        place = 'sinkbasin' if verb == 'clean' else ('microwave' if verb == 'heat' else 'fridge')
        msg = 'Before final placement, use the available ' + verb + ' action on the carried ' + target + ' with the ' + place + '. Do not put the untransformed item at the destination.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to a ' + dest + ' and use the put action there; avoid putting it in other receptacle types.'
    elif stage == 'put_target' and target and dest:
        msg = 'The ' + target + ' is ready; put it in/on the ' + dest + ' and do not take it back or loop on look/inventory.'
    elif stage == 'take_target' and target and getv(ctx, 'world.target_found', False):
        msg = 'A requested ' + target + ' is available here. Take that target type instead of unrelated objects.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

